const modules=[
['3.1','Cell membrane','Understand the boundary. Predict what crosses it.'],
['3.2','Cellular organelles','Meet the structures that build, ship, power and recycle.'],
['3.3','Nucleus & DNA','Unpack the genome and copy its instructions.'],
['3.4','Protein synthesis','Follow information from a gene to a working protein.'],
['3.5','Growth & division','Track DNA, chromosomes and the stages of mitosis.'],
['3.6','Differentiation','Discover how a shared genome creates specialized cells.']];
document.querySelector('#app').innerHTML=`<header class="app-header"><a class="brand" href="./">soma<span>CELL STUDIO</span></a><div class="header-links"><span class="pill">CHAPTER 03</span><a href="../">↗ Organs & body atlas</a></div></header><div class="shell"><aside class="sidebar"><p class="eyebrow">THE CELLULAR LEVEL</p><nav>${modules.map(m=>`<button class="module-nav" data-module="${m[0]}"><b>${m[0]}</b>${m[1]}</button>`).join('')}</nav><div class="sidebar-bottom">A separate learning space for Chapter 3.<a href="../">← Chapters 1–2 studio</a></div></aside><main id="main" class="main"><div class="main-heading"><div><p class="eyebrow">SMALL STRUCTURES. EXTRAORDINARY POSSIBILITIES.</p><h1>Life, from the inside.</h1></div><span class="pill">6 connected modules</span></div><section class="hero"><div class="hero-copy"><p class="eyebrow">WELCOME TO CELL STUDIO</p><h2>One cell. A whole world to discover.</h2><p id="module-summary">Move from membranes to molecules, then watch one cell divide and specialize. This chapter map is the first published stage of your new studio.</p><div class="hero-actions"><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/3-introduction" target="_blank" rel="noopener">Read Chapter 3 ↗</a></div></div><div class="cell-emblem" aria-hidden="true"><i></i><i></i><i></i></div></section><div class="module-grid">${modules.map(m=>`<button class="module-card" data-module="${m[0]}"><div class="card-top"><span class="eyebrow">SECTION ${m[0]}</span><span>↗</span></div><h3>${m[1]}</h3><p>${m[2]}</p><div class="card-foot">Explore the chapter map<span>→</span></div></button>`).join('')}</div><footer class="footer">OpenStax A&P 2e · Chapter 3 · CC BY-NC-SA 4.0<span>Stage 1 · Chapter map published</span></footer></main></div>`;
document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{const m=modules.find(m=>m[0]===b.dataset.module);document.querySelector('#module-summary').textContent=`${m[0]} · ${m[1]}. ${m[2]} Interactive lessons, diagrams and practice for this topic are being built in the next stages.`;});
